service.method:
/*DeliveryAddress.doQueryDeliveryAddress*/

	SELECT
		  DA_NUMBER
	FROM SDLAD
	WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND USER_ID = ${session.ID}		
	AND USER_ADDR_FLAG = 'Y'
	AND NVL(DEL_FLAG,'N') = 'N'

/*DeliveryAddress.doSave*/

	INSERT INTO SDLAD(
		  HOUSE_CODE
		, DA_NUMBER
		, USER_ID
		, REC_USER_NAME
		, DEPT_NAME
		, ZIP_CODE
		, ADDRESS_LOC
		, ADDRESS_LOC_TEXT
		, PHONE_NO1
		, PHONE_NO2
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, CHANGE_DATE
		, CHANGE_TIME
		, CHANGE_USER_ID
		, DEL_FLAG
	)VALUES(
		  ${session.HOUSE_CODE}
		, ${DA_NUMBER}
		, ${session.ID}
		, ${REC_USER_NAME}
		, ${DEPT_NAME}
		, ${ZIP_CODE}
		, ${ADDRESS_LOC}
		, ${ADDRESS_LOC_TEXT}
		, ${PHONE_NO1}
		, ${PHONE_NO2}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, 'N'
	)

/*DeliveryAddress.doUpdate*/

	UPDATE SDLAD SET
		  REC_USER_NAME      = ${REC_USER_NAME}
		, DEPT_NAME          = ${DEPT_NAME}
		, ZIP_CODE           = ${ZIP_CODE}
		, ADDRESS_LOC        = ${ADDRESS_LOC}
		, ADDRESS_LOC_TEXT   = ${ADDRESS_LOC_TEXT}
		, PHONE_NO1          = ${PHONE_NO1}
		, PHONE_NO2          = ${PHONE_NO2}
		, CHANGE_DATE        = ${current.DATE}
		, CHANGE_TIME        = ${current.TIME}
		, CHANGE_USER_ID     = ${session.ID}
	WHERE HOUSE_CODE	   = ${session.HOUSE_CODE}
	  AND DA_NUMBER		   = ${DA_NUMBER}
	  AND USER_ID		   = ${session.ID}
